<?php
require_once __DIR__.'/../includes/bootstrap.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=db()->prepare('SELECT id,email,name FROM users WHERE email=? LIMIT 1');$q->execute([trim($_POST['email'])]);$u=$q->fetch();if($u){$token=secure_random(16);$hash=password_hash($token,PASSWORD_DEFAULT);$s=db()->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))');$s->execute([$u['id'],$hash]);EmailService::send($u['email'],'Password Reset','Use this token in development: <b>'.e($token).'</b>');$msg='Reset token generated. In local demo mode it is shown below: '.$token;}else$msg='If that email exists, a reset process has been initiated.';}?><!doctype html><html><body style='font-family:Arial;max-width:520px;margin:60px auto'><h2>Reset Password</h2><?php if($msg):?><div><?=e($msg)?></div><?php endif;?><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input name='email' type='email' placeholder='Email' required style='width:100%;padding:10px;margin:10px 0'><button>Generate reset</button></form></body></html>